insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_royal_impostor_q01_fenn_clue","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q01_fenn_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q01_painter_witness","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q01_painter_witness_copy","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q01_will_witness","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q02_fenn_clue","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q02_garrick_witness","speaker_external_id":"Main Gate Gaurd 2","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q02_tomlin_start","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q03_fenn_done","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q03_fenn_start","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q04_fenn_done","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q04_fenn_start","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q05_fenn_checked","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q05_fenn_done","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}},{"key":"the_royal_impostor_q05_fenn_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":0,"content":"נפלא. שני דברים כבר חזרו לאנשים שחיפשו אותם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":1,"content":"ויל קיבל את החפץ שלו, והציירת קיבלה את שלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":2,"content":"כשהפטיש שייך לוויל, אנחנו אומרים his hammer - הפטיש שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":3,"content":"כשהמברשת שייכת לציירת, אנחנו אומרים her brush - המברשת שלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"he","line_order":4,"content":"בשער הראשי מחכים שני שומרים עם סיפור משלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_clue","locale":"en","line_order":5,"content":"Go to Tomlin at the Main Gate.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":0,"content":"אחרי החגיגה הכיכר נראית שקטה, אבל העגלה הזאת מלאה בסיפורים קטנים.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":1,"content":"אנשים השאירו כאן דברים יקרים, ועכשיו כל אחד מחפש את מה שאבד לו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":2,"content":"ויל הנפח אמר שהדבר שהוא צריך מחכה בתוך אחד מהארגזים.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":3,"content":"אם תמצאו אותו, קחו אותו אליו. הוא ודאי יזהה אותו מיד.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"he","line_order":4,"content":"אחר כך המשיכו אל הציירת. גם היא מחכה לחדשות.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_fenn_start","locale":"en","line_order":5,"content":"Go to Will the Blacksmith.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness","locale":"he","line_order":0,"content":"איזה מזל שהגעתם! מאז החגיגה אני מחפשת דבר חשוב לי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness","locale":"he","line_order":1,"content":"הוא נמצא בתוך אחד מהארגזים, אבל בין כל הדברים קשה לדעת מה שלי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness","locale":"he","line_order":2,"content":"כשתמצאו אותו, הביאו אותו אליי. אני אזהה אותו לפי הידית והצבע.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness_copy","locale":"he","line_order":0,"content":"Yes, this is my brush.\nזאת המברשת שלי. עכשיו אוכל לחזור לצייר.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness_copy","locale":"he","line_order":1,"content":"חזרו אל שומר העיר וספרו לו שהחיפוש התקדם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_painter_witness_copy","locale":"he","line_order":2,"content":"אבל לפני זה תעברו בתחנה של Exam Table.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"he","line_order":0,"content":"שלום, חברים! טוב שבאתם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"he","line_order":1,"content":"הדבר שאני הכי צריך נמצא בתוך אחד מהארגזים, אבל לא הצלחתי למצוא אותו לבד.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"he","line_order":2,"content":"אה... הנה הפטיש שלי הבאתם לי אותו! Yes, this is my hammer. ","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q01_will_witness","locale":"he","line_order":3,"content":"הציירת מחכה לעזרה שלכם. לכו לשמוע מה קרה לה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":0,"content":"הצלחתם לעזור לשומרים, והם כבר יודעים למי שייך הדבר שנמצא.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":1,"content":"כשהכריכים שייכים לשומרים, אנחנו אומרים their sandwiches - הכריכים שלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":2,"content":"ליד העגלה מצאנו גם דף ישן וקרוע.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"he","line_order":3,"content":"הציירת מבינה בצבעים ובסימנים. אולי היא תצליח להחזיר לדף את הסדר.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_fenn_clue","locale":"en","line_order":4,"content":"Go to the Painter.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":0,"content":"טומלין כבר סיפר לכם על הצרה שלנו, נכון?","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":1,"content":"גם אני מצאתי משהו קטן ליד העגלה. אולי הוא יעזור לכם בדרך.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"en","line_order":2,"content":"This is your clue.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":3,"content":"זה הרמז שלכם. שמרו עליו היטב ואל תתנו לו ללכת לאיבוד.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_garrick_witness","locale":"he","line_order":4,"content":"כשתהיו מוכנים, חזרו אל שומר העיר עם מה שגיליתם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":0,"content":"הנה אתם! בדיוק קיווינו שתגיעו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":1,"content":"אנחנו מחפשים דבר ששייך לשנינו, והוא נעלם בזמן החגיגה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":2,"content":"אם תמצאו אותו, חזרו וספרו לנו. אולי סוף סוף נוכל לנשום לרווחה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"en","line_order":3,"content":"These are our sandwiches.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":4,"content":"אלה הכריכים שלנו. מסתבר שהבטן שלנו זוכרת אותם טוב יותר מאיתנו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q02_tomlin_start","locale":"he","line_order":5,"content":"גאריק מצא רמז קטן. דברו איתו לפני שתמשיכו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":0,"content":"מצוין. עכשיו אפשר שוב לקרוא את הרשימה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":1,"content":"רואים בה בבירור למי צריכים להחזיר את הדברים שנמצאו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":2,"content":"אבל בתחתית נשאר סימן מוזר.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":3,"content":"ויל מכיר את הסימן הזה ויכול להבין מה הוא אומר.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"he","line_order":4,"content":"קחו אליו את הרשימה ושמעו ממנו מה הלאה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_done","locale":"en","line_order":5,"content":"Go to Will the Blacksmith.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":0,"content":"תראו מה מצאתי! הרשימה הזאת עברה כמעט כמו הכיכר עצמה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":1,"content":"כמה מילים כמעט נעלמו, אבל עדיין אפשר להציל את המשמעות שלהן.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":2,"content":"בתוך הרשימה מסתתר רמז על הדברים ועל הבעלים שלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":3,"content":"קודם גשו לשולחן, ואחר כך חזרו אל העגלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q03_fenn_start","locale":"he","line_order":4,"content":"אם הכול יסתדר, הרשימה תוכל לספר לנו את האמת.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_done","locale":"he","line_order":0,"content":"זה עבד! הארגז שוב פתוח.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_done","locale":"he","line_order":1,"content":"עכשיו אפשר להחזיר את הדברים לאנשים שאיבדו אותם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_done","locale":"he","line_order":2,"content":"הרשימה כבר אצלכם, והבדיקה האחרונה מחכה אצל שומר העיר.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_done","locale":"he","line_order":3,"content":"קחו אליו הכול. הוא יוודא שאף אחד לא נשאר בלי הדבר שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_done","locale":"en","line_order":4,"content":"Go back to the City Guard.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_start","locale":"he","line_order":0,"content":"עכשיו אני מבין. הסימן הזה קשור לארגז האבידות.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_start","locale":"he","line_order":1,"content":"נעלו אותו כדי שהדברים שנמצאו לא יגיעו לידיים הלא נכונות.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_start","locale":"he","line_order":2,"content":"הדרך לתשובה מתחילה ליד העגלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_start","locale":"he","line_order":3,"content":"אחר כך גשו לשולחן וחזרו שוב אל העגלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_start","locale":"he","line_order":4,"content":"אל תמהרו. במנעולים כאלה כל פרט קטן חשוב.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q04_fenn_start","locale":"he","line_order":5,"content":"כשהכול יסתדר, המנעול ייפתח.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_checked","locale":"he","line_order":0,"content":"בדקתי את התשובות שלכם. כל דבר שוב נמצא ליד הבעלים שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_checked","locale":"he","line_order":1,"content":"his hammer - הפטיש שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_checked","locale":"he","line_order":2,"content":"her brush - המברשת שלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_checked","locale":"he","line_order":3,"content":"their sandwiches - הכריכים שלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_checked","locale":"he","line_order":4,"content":"נשאר רק לסגור את החיפוש ולסדר את העגלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":0,"content":"עשיתם את זה. שום דבר לא נשאר בלי בעלים.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":1,"content":"ויל שוב מחזיק בפטיש שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":2,"content":"הציירת שוב יכולה לצייר במברשת שלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":3,"content":"והשומרים מצאו את הכריכים שלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":4,"content":"בדרך למדנו לומר my, your, his, her, our ו their.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":5,"content":"כך הצלחנו להבין למי שייך כל דבר.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":6,"content":"רגע... השומרים כבר הספיקו לאכול את הכריכים.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":7,"content":"לפחות הם מצאו אותם בזמן. עבודה מצוינת!","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_done","locale":"he","line_order":8,"content":"קבלו 10 מטבעות.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":0,"content":"כמעט סיימנו. נשאר רק לעבור בזהירות על החלק האחרון של הדרך.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":1,"content":"התחילו אצל השולחן, אחר כך גשו אל העגלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":2,"content":"משם חזרו שוב אל השולחן, ואז אליי.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":3,"content":"אני אחכה כאן ואעזור לכם להחזיר הכול למקום.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_q05_fenn_start","locale":"he","line_order":4,"content":"אל דאגה. כבר מצאתם את הרמזים החשובים ביותר.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
